	for (int i = 0; i < 8; i++) {
		AsciiString name;
		name.format("ControlBar.wnd:ButtonPlayer%d", i);
		buttonPlayerID[i] = TheNameKeyGenerator->nameToKey(name);
		buttonPlayer[i] = TheWindowManager->winGetWindowFromId(ObserverPlayerListWindow, buttonPlayerID[i]);
		name.format("ControlBar.wnd:StaticTextPlayer%d", i);
		staticTextPlayerID[i] = TheNameKeyGenerator->nameToKey(name);
		staticTextPlayer[i] = TheWindowManager->winGetWindowFromId(ObserverPlayerListWindow, staticTextPlayerID[i]);
	}
	staticTextNumberOfUnits = TheWindowManager->winGetWindowFromId(0, TheNameKeyGenerator->nameToKey("ControlBar.wnd:StaticTextNumberOfUnits"));
	staticTextNumberOfBuildings = TheWindowManager->winGetWindowFromId(0, TheNameKeyGenerator->nameToKey("ControlBar.wnd:StaticTextNumberOfBuildings"));
