// FUNCTION: BFME2 0x0050E08E size=855 name=?populateObserverList@ControlBar@@QAEXXZ evidence=N:ledger tier=B hypothesis:Z

void ControlBar::populateObserverList()
{
	int currentButton = 0, i;
	if (TheRecorder->isMultiplayer()) {
		for (i = 0; i < 8; ++i) {
			AsciiString name;
			if (TheGameInfo)
				name = TheGameInfo->getSlot(i)->m_unk0x34;
			Player *player = ThePlayerList->findPlayerWithNameKey(TheNameKeyGenerator->nameToKey(name));
			if (player && player->getPlayerTemplate()) {
				if (player->isPlayerObserver())
					continue;
				Rva00328518(buttonPlayer[currentButton], (int)player);
				GadgetButtonSetEnabledImage_Rva002C0433(buttonPlayer[currentButton], player->getPlayerTemplate()->getEnabledImage());
				buttonPlayer[currentButton]->winSetTooltip(player->m_playerDisplayName);
				buttonPlayer[currentButton]->winHide(false);
				buttonPlayer[currentButton]->winSetStatus(0x200000);
				const GameSlot *slot = TheGameInfo->getConstSlot(currentButton);
				int playerColor = player->getPlayerColor();
				int backColor = 0xFF000000;
				staticTextPlayer[currentButton]->winSetEnabledTextColors(playerColor, backColor);
				staticTextPlayer[currentButton]->winHide(false);
				AsciiString teamStr;
				teamStr.format("Team:%d", slot->m_teamNumber + 1);
				if (slot->isAI() && slot->m_teamNumber == -1)
					teamStr.set("Team:AI");
				UnicodeString text;
				text.format(TheGameText->fetchPtr("CONTROLBAR:ObsPlayerLabel"), player->m_playerDisplayName.str(),
					TheGameText->fetch(teamStr).str());
				GadgetStaticTextSetText(staticTextPlayer[currentButton], text);
				++currentButton;
			}
		}
		for (; currentButton < 8; ++currentButton) {
			buttonPlayer[currentButton]->winHide(true);
			staticTextPlayer[currentButton]->winHide(true);
		}
	} else {
		for (i = 0; i < 20; ++i) {
			Player *player = ThePlayerList->getNthPlayer(i);
			if (player && !player->isPlayerObserver() && player->m_playerType == 0) {
				Rva00328518(buttonPlayer[currentButton], (int)player);
				GadgetButtonSetEnabledImage_Rva002C0433(buttonPlayer[currentButton], player->getPlayerTemplate()->getEnabledImage());
				buttonPlayer[currentButton]->winSetTooltip(player->m_playerDisplayName);
				buttonPlayer[currentButton]->winHide(false);
				buttonPlayer[currentButton]->winSetStatus(0x200000);
				int playerColor = player->getPlayerColor();
				int backColor = 0xFF000000;
				staticTextPlayer[currentButton]->winSetEnabledTextColors(playerColor, backColor);
				staticTextPlayer[currentButton]->winHide(false);
				GadgetStaticTextSetText(staticTextPlayer[currentButton], player->m_playerDisplayName);
				++currentButton;
				break;
			}
		}
		for (; currentButton < 8; ++currentButton) {
			buttonPlayer[currentButton]->winHide(true);
			staticTextPlayer[currentButton]->winHide(true);
		}
	}
}

// FUNCTION: BFME2 0x0050E3E5 size=705 name=?populateObserverInfoWindow@ControlBar@@QAEXXZ evidence=N:ledger tier=B hypothesis:Z

void ControlBar::populateObserverInfoWindow()
{
	if (ObserverPlayerInfoWindow->winIsHidden())
		return;
	if (m_observerLookAtPlayer == 0) {
		ObserverPlayerInfoWindow->winHide(true);
		ObserverPlayerListWindow->winHide(false);
		populateObserverList();
		return;
	}
	UnicodeString text;
	KindOfMaskType setMask;
	KindOfMaskType clearMask;
	setMask.set(KINDOF_SCORE);
	clearMask.set(KINDOF_STRUCTURE);
	text.format(L"%d", m_observerLookAtPlayer->countObjects(setMask, clearMask));
	GadgetStaticTextSetText(staticTextNumberOfUnits, text);
	setMask.clear();
	setMask.set(KINDOF_SCORE);
	setMask.set(KINDOF_STRUCTURE);
	clearMask.clear();
	int buildings = m_observerLookAtPlayer->countObjects(setMask, clearMask);
	setMask.clear();
	setMask.set(KINDOF_SCORE_CREATE);
	setMask.set(KINDOF_STRUCTURE);
	buildings += m_observerLookAtPlayer->countObjects(setMask, clearMask);
	setMask.clear();
	setMask.set(KINDOF_SCORE_DESTROY);
	setMask.set(KINDOF_STRUCTURE);
	buildings += m_observerLookAtPlayer->countObjects(setMask, clearMask);
	text.format(L"%d", buildings);
	GadgetStaticTextSetText(staticTextNumberOfBuildings, text);
	text.format(L"%d", m_observerLookAtPlayer->getScoreKeeper()->getTotalUnitsDestroyed());
	GadgetStaticTextSetText(staticTextNumberOfUnitsKilled, text);
	text.format(L"%d", m_observerLookAtPlayer->getScoreKeeper()->getTotalUnitsLost());
	GadgetStaticTextSetText(staticTextNumberOfUnitsLost, text);
	GadgetStaticTextSetText(staticTextPlayerName, m_observerLookAtPlayer->m_playerDisplayName);
	staticTextPlayerName->winSetEnabledTextColors(m_observerLookAtPlayer->getPlayerColor(), 0xFF000000);
	winFlag->winSetEnabledImage(0, m_observerLookAtPlayer->getPlayerTemplate()->getFlagWaterMarkImage());
	winGeneralPortrait->winHide(false);
}

// FUNCTION: BFME2 0x0050E6A6 size=208 name=?ControlBarObserverSystem@@YA?AW4WindowMsgHandledType@@PAVGameWindow@@III@Z evidence=N:ledger tier=B hypothesis:Z

WindowMsgHandledType ControlBarObserverSystem(GameWindow *window, unsigned int msg, unsigned int mData1, unsigned int mData2)
{
	switch (msg) {
	case 1:
	case 0x4006:
	case 0x4007:
		break;
	case 0x4008:
	case 0x4009: {
		GameWindow *control = (GameWindow *)mData1;
		int controlID = control->winGetWindowId();
		if (controlID == buttonCancelID) {
			TheControlBar->setObserverLookAtPlayer(0);
			ObserverPlayerInfoWindow->winHide(true);
			ObserverPlayerListWindow->winHide(false);
			TheControlBar->populateObserverList();
		}
		for (int i = 0; i < 8; ++i) {
			if (controlID == buttonPlayerID[i]) {
				ObserverPlayerInfoWindow->winHide(false);
				ObserverPlayerListWindow->winHide(true);
				TheControlBar->setObserverLookAtPlayer((Player *)GadgetButtonGetData(buttonPlayer[i]));
				if (TheControlBar->getObserverLookAtPlayer())
					TheControlBar->populateObserverInfoWindow();
				return MSG_HANDLED;
			}
		}
		break;
	}
	default:
		return MSG_IGNORED;
	}
	return MSG_HANDLED;
}
